1	import * as fs from 'fs';
2	import * as path from 'path';
3	import { parseMarkdown } from './parser.js';
4	import { BuildOptions, PageMetadata } from './types.js';
5	
6	export class SiteGenerator {
7	  private contentDir: string;
8	  private outputDir: string;
9	
10	  constructor(options: BuildOptions) {
11	    this.contentDir = options.contentDir;
12	    this.outputDir = options.outputDir;
13	  }
14	
15	  private ensureDir(dirPath: string): void {
16	    if (!fs.existsSync(dirPath)) {
17	      fs.mkdirSync(dirPath, { recursive: true });
18	    }
19	  }
20	
21	  private getMarkdownFiles(): string[] {
22	    if (!fs.existsSync(this.contentDir)) {
23	      return [];
24	    }
25	
26	    return fs
27	      .readdirSync(this.contentDir)
28	      .filter((file) => file.endsWith('.md'))
29	      .sort();
30	  }
31	
32	  private generatePageHtml(title: string, content: string): string {
33	    return `<!DOCTYPE html>
34	<html lang="en">
35	<head>
36	  <meta charset="UTF-8">
37	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
38	  <title>${this.escapeHtml(title)}</title>
39	  <style>
40	    body {
41	      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
42	      line-height: 1.6;
43	      max-width: 800px;
44	      margin: 0 auto;
45	      padding: 20px;
46	      color: #333;
47	    }
48	    h1, h2, h3, h4, h5, h6 { margin-top: 1.5em; }
49	    code {
50	      background: #f0f0f0;
51	      padding: 2px 6px;
52	      border-radius: 3px;
53	      font-family: 'Courier New', monospace;
54	    }
55	    pre {
56	      background: #f5f5f5;
57	      padding: 10px;
58	      border-radius: 5px;
59	      overflow-x: auto;
60	    }
61	    pre code { background: none; padding: 0; }
62	    a { color: #0066cc; text-decoration: none; }
63	    a:hover { text-decoration: underline; }
64	    .nav { margin-bottom: 20px; }
65	    .nav a { margin-right: 15px; }
66	  </style>
67	</head>
68	<body>
69	  <div class="nav">
70	    <a href="index.html">← Home</a>
71	  </div>
72	  <h1>${this.escapeHtml(title)}</h1>
73	  <div>${content}</div>
74	</body>
75	</html>`;
76	  }
77	
78	  private generateIndexHtml(pages: PageMetadata[]): string {
79	    const pagesList = pages
80	      .map(
81	        (page) => `    <li>
82	      <a href="${this.escapeHtml(page.url)}">${this.escapeHtml(page.title)}</a>
83	      ${page.date ? `<span style="color: #666; margin-left: 10px;">${this.escapeHtml(page.date)}</span>` : ''}
84	      ${page.tags.length > 0 ? `<div style="margin-top: 5px;"><small>${page.tags.map((tag) => `<span style="display: inline-block; background: #eee; padding: 2px 8px; border-radius: 3px; margin-right: 5px;">${this.escapeHtml(tag)}</span>`).join('')}</small></div>` : ''}
85	    </li>`
86	      )
87	      .join('\n');
88	
89	    return `<!DOCTYPE html>
90	<html lang="en">
91	<head>
92	  <meta charset="UTF-8">
93	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
94	  <title>Static Site</title>
95	  <style>
96	    body {
97	      font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
98	      line-height: 1.6;
99	      max-width: 800px;
100	      margin: 0 auto;
101	      padding: 20px;
102	      color: #333;
103	    }
104	    h1 { margin-top: 0; }
105	    ul { list-style: none; padding: 0; }
106	    li {
107	      padding: 15px;
108	      border: 1px solid #eee;
109	      margin-bottom: 10px;
110	      border-radius: 5px;
111	    }
112	    li:hover { background: #f9f9f9; }
113	    a { color: #0066cc; text-decoration: none; }
114	    a:hover { text-decoration: underline; }
115	  </style>
116	</head>
117	<body>
118	  <h1>Pages</h1>
119	  ${pages.length > 0 ? `<ul>\n${pagesList}\n  </ul>` : '<p>No pages found.</p>'}
120	</body>
121	</html>`;
122	  }
123	
124	  private escapeHtml(text: string): string {
125	    return text
126	      .replace(/&/g, '&amp;')
127	      .replace(/</g, '&lt;')
128	      .replace(/>/g, '&gt;')
129	      .replace(/"/g, '&quot;')
130	      .replace(/'/g, '&#39;');
131	  }
132	
133	  async build(): Promise<void> {
134	    this.ensureDir(this.outputDir);
135	
136	    const markdownFiles = this.getMarkdownFiles();
137	    const pages: PageMetadata[] = [];
138	
139	    for (const file of markdownFiles) {
140	      const filePath = path.join(this.contentDir, file);
141	      const content = fs.readFileSync(filePath, 'utf-8');
142	      const parsed = await parseMarkdown(content);
143	
144	      const title = parsed.frontmatter.title || file.replace('.md', '');
145	      const slug = file.replace('.md', '.html');
146	      const outputPath = path.join(this.outputDir, slug);
147	
148	      fs.writeFileSync(outputPath, this.generatePageHtml(title, parsed.html));
149	
150	      pages.push({
151	        filename: file,
152	        title,
153	        date: parsed.frontmatter.date ? String(parsed.frontmatter.date) : undefined,
154	        tags: Array.isArray(parsed.frontmatter.tags)
155	          ? parsed.frontmatter.tags.map((tag) => String(tag))
156	          : [],
157	        url: slug,
158	      });
159	    }
160	
161	    const indexPath = path.join(this.outputDir, 'index.html');
162	    fs.writeFileSync(indexPath, this.generateIndexHtml(pages));
163	
164	    console.log(`✓ Generated ${pages.length} page(s) to ${this.outputDir}`);
165	  }
166	}
