3	import * as path from 'path';
4	import { SiteGenerator } from './generator.js';
5	
6	function parseArgs(args: string[]): { command: string; contentDir: string; outputDir: string } {
7	  let command = 'build';
8	  let contentDir = './content';
9	  let outputDir = './dist';
10	
11	  for (let i = 0; i < args.length; i++) {
12	    const arg = args[i];
13	
14	    if (!arg.startsWith('-')) {
15	      command = arg;
16	      continue;
17	    }
18	
19	    if (arg === '--content' && i + 1 < args.length) {
20	      contentDir = args[++i];
21	    } else if (arg === '--output' && i + 1 < args.length) {
22	      outputDir = args[++i];
23	    }
24	  }
25	
26	  return { command, contentDir, outputDir };
27	}
28	
29	async function main(): Promise<void> {
30	  const args = process.argv.slice(2);
31	  const { command, contentDir, outputDir } = parseArgs(args);
32	
33	  if (command !== 'build') {
34	    console.error(`Unknown command: ${command}`);
35	    process.exit(1);
36	  }
37	
38	  const resolvedContentDir = path.resolve(contentDir);
39	  const resolvedOutputDir = path.resolve(outputDir);
40	
41	  try {
42	    const generator = new SiteGenerator({
43	      contentDir: resolvedContentDir,
44	      outputDir: resolvedOutputDir,
45	    });
46	
47	    await generator.build();
48	  } catch (error) {
49	    console.error('Error building site:', error instanceof Error ? error.message : String(error));
50	    process.exit(1);
51	  }
52	}
53	
54	main();
